/* Private Blackbook. Every export is assembled locally from the user's own records. */
const TYPES = {word:'Slovo',palette:'Paleta',reference:'Reference',note:'Poznámka',sound:'Zvukový záznam – text',sketch:'Skica – poznámka'};
const DISCIPLINES = {dj:'DJ',mc:'MC',writer:'Writer',breaking:'Breaking',knowledge:'Knowledge'};
const asText = value => {if(value===null||value===undefined)return '';if(typeof value==='string')return value;if(typeof value==='number'||typeof value==='boolean')return String(value);try{return JSON.stringify(value)||'';}catch{return '';}};
const esc = value => asText(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const arr = value => Array.isArray(value) ? value : [];
const uid = () => globalThis.crypto?.randomUUID?.() || `local-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
const stamp = () => new Date().toISOString();
const latest = artifact => arr(artifact.versions).at(-1) || {};
const date = value => (typeof value==='string'||typeof value==='number')&&Number.isFinite(Date.parse(value)) ? new Date(value).toLocaleString('cs-CZ') : 'Čas nebyl zaznamenán';
const hex = value => typeof value==='string'&&/^#(?:[\da-f]{3}|[\da-f]{4}|[\da-f]{6}|[\da-f]{8})$/i.test(value) ? value : '#FFD600';
const numeric=value=>(typeof value==='number'||typeof value==='string')?Number(value):NaN;
const limit = (value,min,max) => Math.max(min,Math.min(max,numeric(value)||min));
function safeUrl(value) {try {const u=new URL(value);return /^https?:$/.test(u.protocol)?u.href:null;}catch{return null;}}
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const validId = value => typeof value === 'string' && /^[a-zA-Z0-9_.:-]{1,160}$/.test(value);
function meta(state) {
 const raw=object(state?.drafts?.journal)?state.drafts.journal:{},ids=value=>[...new Set(arr(value).filter(validId))].slice(0,1000);
 return {base:['studio','workshop','library'].includes(raw.base)?raw.base:'studio',
  ...(Array.isArray(raw.selected)?{selected:ids(raw.selected)}:{}),desk:ids(raw.desk),wall:ids(raw.wall),
  links:arr(raw.links).filter(l=>object(l)&&validId(l.id)&&validId(l.from)&&validId(l.to)&&typeof l.note==='string').slice(0,1000).map(l=>({id:l.id,from:l.from,to:l.to,note:l.note.slice(0,1000)})),
  vocabulary:arr(raw.vocabulary).filter(v=>object(v)&&validId(v.id)&&typeof v.term==='string'&&typeof v.meaning==='string').slice(0,1000).map(v=>({id:v.id,term:v.term.slice(0,120),meaning:v.meaning.slice(0,3000),artifactId:validId(v.artifactId)?v.artifactId:''}))};
}
function selectedArtifacts(state, selectedIds) {const chosen=selectedIds===undefined?meta(state).selected:selectedIds;return arr(state.artifacts).filter(a=>chosen===undefined||arr(chosen).includes(a.id));}
export function lineChanges(before, after) {const old=asText(before).split('\n'), newer=asText(after).split('\n');return newer.map((text,index)=>({text,changed:text!==(old[index]??''),index}));}
export function notebookStats(state) {return {artifacts:arr(state.artifacts).length,versions:arr(state.artifacts).reduce((n,a)=>n+arr(a.versions).length,0),materials:arr(state.inventory).length,links:arr(meta(state).links).length};}
export function renderSketch(strokes, {width=900,height=440}={}) {
 const paths=arr(strokes).filter(object).slice(0,600).map(stroke=>{
  const points=arr(stroke.points).slice(0,4000).map(p=>[numeric(Array.isArray(p)?p[0]:p?.x),numeric(Array.isArray(p)?p[1]:p?.y)]).filter(p=>p.every(Number.isFinite)).map(p=>[limit(p[0],0,width),limit(p[1],0,height)]);
  if(!points.length)return '';
  const d=points.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(2)},${p[1].toFixed(2)}`).join(' ')+(points.length===1?` l0.01,0.01`:'');
  return `<path d="${d}" fill="none" stroke="${hex(stroke.color)}" stroke-width="${limit(stroke.width||stroke.size||5,1,60)}" stroke-linecap="round" stroke-linejoin="round"/>`;
 }).join('');
 return paths?`<svg class="journal-sketch" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Vlastní uložená skica"><rect width="100%" height="100%" fill="#080808"/>${paths}</svg>`:'';
}
function paletteHtml(palette) {return arr(palette).filter(item=>typeof item==='string'||object(item)).slice(0,12).map(item=>{const color=typeof item==='string'?item:item?.color;return `<span class="journal-swatch" style="--swatch:${hex(color)}"><i></i>${esc(color)}${item?.purpose?` / ${esc(item.purpose)}`:''}</span>`;}).join('');}
function versionHtml(version, previous) {return `<section class="journal-version"><p class="journal-meta">${esc(date(version.createdAt))}</p>${renderSketch(version.strokes)}${paletteHtml(version.palette)}<div class="journal-lines">${lineChanges(previous?.text,version.text).map(line=>`<div data-i18n-user${line.changed&&previous?' class="journal-changed"':''}>${esc(line.text)||'&nbsp;'}</div>`).join('')}</div>${version.decision?`<h4>Rozhodnutí / co jsem změnil</h4><p data-i18n-user>${esc(version.decision)}</p>`:''}${version.nextStep?`<h4>Další krok</h4><p data-i18n-user>${esc(version.nextStep)}</p>`:''}</section>`;}
export function notebookText(state,{selectedIds}={}) {
 const artifacts=selectedArtifacts(state,selectedIds);
 return [`CAISIK / BLACKBOOK — ${state.profile?.alias||'Vlastní tvorba'}`,`Export ${stamp()}`, 'Soukromá lokální data. Export neobsahuje nahrávky uchované pouze v paměti otevřené karty.','',...artifacts.flatMap(a=>[`${DISCIPLINES[a.discipline]||a.discipline} / ${a.title}`,...arr(a.versions).flatMap((v,i)=>[`VERZE ${i+1} / ${asText(v.createdAt)}`,asText(v.text),`Rozhodnutí: ${asText(v.decision)||'—'}`,`Další krok: ${asText(v.nextStep)||'—'}`]),'']), 'INVENTÁŘ',...arr(state.inventory).flatMap(i=>[`${TYPES[asText(i.type)]||asText(i.type)}: ${asText(i.title)}`,asText(i.text),i.source?`Zdroj: ${asText(i.source)}`:'','']),'VLASTNÍ SLOVNÍK',...arr(meta(state).vocabulary).map(v=>`${v.term}: ${v.meaning}`)].join('\n');
}
export function renderPortableNotebook(state,{selectedIds}={}) {
 const artifacts=selectedArtifacts(state,selectedIds), ids=new Set(artifacts.map(a=>a.id));
 const cards=artifacts.map(a=>`<article><p class="eyebrow">${esc(DISCIPLINES[a.discipline]||a.discipline)} / ${arr(a.versions).length} vlastních verzí</p><h2 data-i18n-user>${esc(a.title)}</h2>${arr(a.versions).map((v,i)=>`<h3>Verze ${i+1}</h3>${versionHtml(v,a.versions[i-1])}`).join('')}</article>`).join('');
 const links=arr(meta(state).links).filter(l=>ids.has(l.from)&&ids.has(l.to));
 return `<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'"><title>${esc(state.profile?.alias||'CAISIK')} — Blackbook</title><style>body{margin:0;background:#080808;color:#F5F1E8;font:17px/1.6 system-ui,sans-serif}main{max-width:920px;padding:6vw;margin:auto}h1{font-size:clamp(2.5rem,8vw,6rem);line-height:.95;color:#FFD600}h2{font-size:2rem}h3,h4{color:#FFD600}article{padding:2rem 0;border-top:2px solid #FFD600}.eyebrow,.journal-meta{font:12px/1.5 monospace;text-transform:uppercase;color:#ccc}.journal-lines{white-space:pre-wrap;overflow-wrap:anywhere}.journal-changed{border-left:3px solid #FFD600;padding-left:.7rem;background:#FFD60010}.journal-sketch{display:block;width:100%;max-height:500px;border:1px solid #555}.journal-swatch{display:inline-flex;gap:.4em;align-items:center;margin:.3em}.journal-swatch i{width:1em;height:1em;background:var(--swatch);border:1px solid #777}p{white-space:pre-wrap;overflow-wrap:anywhere}a{color:#FFD600}footer{margin-top:3rem;border-top:1px solid #555;padding-top:1rem}</style></head><body><main><p class="eyebrow">CAISIK / UNDERGROUND ALCHEMY / VLASTNÍ VYDÁNÍ</p><h1>${esc(state.profile?.alias||'SELFMADE')}<br>BLACKBOOK.</h1><p>Skutečné verze, skutečná rozhodnutí. ${esc(date(stamp()))}</p>${cards||'<p>Pro toto vydání nebyl vybrán žádný projekt.</p>'}${links.length?`<section><h2>Souvislosti mezi díly</h2>${links.map(l=>`<p>${esc(artifacts.find(a=>a.id===l.from)?.title)} → ${esc(artifacts.find(a=>a.id===l.to)?.title)}<br>${esc(l.note)}</p>`).join('')}</section>`:''}<section><h2>Materiál s původem</h2>${arr(state.inventory).map(i=>`<h3>${esc(i.title)}</h3><p data-i18n-user>${esc(i.text)}</p>${i.source?`<p>Zdroj: ${esc(i.source)}</p>`:''}`).join('')}</section><section><h2>Vlastní slovník</h2>${arr(meta(state).vocabulary).map(v=>`<h3 data-i18n-user>${esc(v.term)}</h3><p data-i18n-user>${esc(v.meaning)}</p>`).join('')}</section><footer>Tento soubor funguje samostatně bez připojení, skriptů a analytiky. Obsahuje vybrané texty, uložené SVG tahy a palety. Neobsahuje audio/video dostupné jen v paměti původní karty. Zveřejnění souboru je tvoje samostatné rozhodnutí.</footer></main></body></html>`;
}

function baseScene(state,count=arr(state.artifacts).length) {
 const works=arr(state.artifacts).slice(0,count).slice(-4),base=meta(state).base||'studio';
 return `<div class="journal-base-scene" data-room="${esc(base)}" role="group" aria-label="Soukromá zeď z vlastních výstupů"><div class="journal-room-sign"><span data-i18n-user>${esc(state.profile?.alias||'TVŮJ PROSTOR')}</span> / ${esc({studio:'STUDIO',workshop:'DÍLNA',library:'KNIHOVNA'}[base]||'STUDIO')}</div><div class="journal-room-works">${works.map(a=>`<div class="journal-room-work">${renderSketch(latest(a).strokes)||`<p data-i18n-user>${esc(latest(a).text).slice(0,100)}</p>`}<strong data-i18n-user>${esc(a.title)}</strong><span>${esc(DISCIPLINES[a.discipline]||a.discipline)} / ${arr(a.versions).length} verzí</span></div>`).join('')||'<p class="journal-room-empty">Tvá první práce tu nechá první stopu.</p>'}</div><div class="journal-room-floor" aria-hidden="true"></div></div><p class="journal-source">Osobní vrstva: ${count} z ${arr(state.artifacts).length} uložených děl. Jde o vlastní virtuální prostor, nikoli skutečnou veřejnou zeď.</p>`;
}
export function mountJournal(root,{store,notify=()=>{}}) {
 root.classList.add('rpg-journal');let unsubscribe=()=>{},objectUrls=[],importCandidate=null,editing=null,view='archive',destroyed=false,lastWriteOK=true,preparedExport=null;
 const message=text=>{notify(text);const el=root.querySelector('[data-journal-status]');if(el)el.textContent=text;};
 const saved=text=>message(lastWriteOK?text:'Operace nebyla trvale potvrzena. Zkontroluj stav úložiště a exportuj práci dostupnou v paměti.');
 const persist=fn=>{const ok=store.update(fn);lastWriteOK=ok;if(!ok)message('Změna je pouze v paměti. Ulož export; trvalé úložiště není dostupné.');return ok;};
 const updateMeta=fn=>persist(s=>{s.drafts ||= {};s.drafts.journal = meta(s);fn(s.drafts.journal,s);});
 function download(name,content,type) {
  preparedExport={name,content:String(content)};
  root.querySelector('[data-journal-export-fallback]')?.remove();
  const fallback=document.createElement('details');fallback.className='journal-export-fallback';fallback.dataset.journalExportFallback='';
  const summary=document.createElement('summary');summary.textContent='Stažení nejde? Zobrazit obsah souboru';fallback.append(summary);
  const link=root.querySelector('[data-journal-download]');link.after(fallback);
  try {const url=URL.createObjectURL(new Blob([content],{type}));objectUrls.push(url);link.href=url;link.download=name;link.hidden=false;link.textContent=`Připraveno: ${name} ↓`;link.click();message('Export je připravený. Odkaz zůstává dostupný; pokud prohlížeč stažení nenabídne, otevři obsah souboru pod ním.');}
  catch {link.hidden=true;message('Stažení se nepodařilo připravit. Obsah je dostupný pod volbou „Stažení nejde?“ — můžeš jej zkopírovat a uložit ručně.');}
 }
 function handleToggle(event) {
  const details=event.target;if(!details.hasAttribute?.('data-journal-export-fallback')||!details.open||!preparedExport||details.querySelector('textarea'))return;
  const instructions=document.createElement('p');instructions.textContent=`Přesný obsah souboru ${preparedExport.name}. Klikni do pole, stiskni Ctrl+A a Ctrl+C (na Macu Cmd+A a Cmd+C) a ulož do textového souboru s uvedeným názvem a kódováním UTF-8. Kopírování nevyžaduje oprávnění ke schránce.`;
  const textarea=document.createElement('textarea');textarea.readOnly=true;textarea.rows=12;textarea.wrap='off';textarea.dataset.journalExportContent='';textarea.setAttribute('aria-label',`Přesný obsah souboru ${preparedExport.name}`);textarea.value=preparedExport.content;
  details.append(instructions,textarea);
 }
 const options=state=>arr(state.artifacts).map(a=>`<option data-i18n-user value="${esc(a.id)}">${esc(a.title)}</option>`).join('');
 function render() {
  if(destroyed)return;const state=store.get(), info=meta(state), stats=notebookStats(state), artifacts=arr(state.artifacts), selected=new Set(info.selected===undefined?artifacts.map(a=>a.id):info.selected), inventory=arr(state.inventory),desk=new Set(arr(info.desk));
  root.innerHTML=`<div class="journal-heading"><div><p class="journal-kicker">TVŮJ PROCES / TVŮJ ARCHIV</p><h2>BLACKBOOK<span>.</span></h2><p>První pokus má stejnou hodnotu jako poslední. Tady vidíš, co se opravdu změnilo.</p></div><div class="journal-count"><strong>${stats.artifacts}</strong><span>děl / ${stats.versions} verzí<br>${stats.materials} materiálů</span></div></div>
  <div class="journal-toolbar" role="group" aria-label="Oddíly Blackbooku">${[['archive','Kronika'],['inventory','Inventář & stůl'],['connections','Souvislosti'],['edition','Vlastní vydání'],['backup','Záloha & obnova']].map(([id,label])=>`<button type="button" data-journal-view="${id}" aria-pressed="${view===id}">${label}</button>`).join('')}</div><p class="journal-notice" data-journal-status role="status">Pouze v tomto prohlížeči. Nic se automaticky nezveřejňuje.</p><a data-journal-download hidden></a>
  <div data-journal-panel="archive"${view==='archive'?'':' hidden'}><div data-journal-world>${baseScene(state)}</div><label class="journal-world-slider">Jak se můj prostor naplňuje<input type="range" data-journal-world-step min="0" max="${artifacts.length||1}" value="${artifacts.length}" step="1"${artifacts.length?'':' disabled'} aria-label="Počet vlastních děl v osobním světě"></label><div class="journal-base"><label>Moje základna<select data-journal-base><option value="studio"${info.base==='studio'?' selected':''}>Studio / zvuk a hlas</option><option value="workshop"${info.base==='workshop'?' selected':''}>Dílna / písmo a barva</option><option value="library"${info.base==='library'?' selected':''}>Knihovna / myšlenky</option></select></label><p>Vlastní díla a rozpracovaný materiál jsou tvoje stopy ve světě. Základna patří tobě.</p></div>${artifacts.length?`<div class="journal-projects">${artifacts.slice().reverse().map(a=>`<article class="journal-project"><p class="journal-kicker">${esc(DISCIPLINES[a.discipline]||a.discipline)} / ${esc(date(a.updatedAt||a.createdAt))}</p><h3 data-i18n-user>${esc(a.title)}</h3>${renderSketch(latest(a).strokes)}<p data-i18n-user>${esc(latest(a).text).slice(0,400)}${asText(latest(a).text).length>400?'…':''}</p><div class="journal-project-actions"><button type="button" data-journal-artifact="${esc(a.id)}">Otevřít ${arr(a.versions).length} verzí ↗</button><label><input type="checkbox" data-journal-curate="${esc(a.id)}"${selected.has(a.id)?' checked':''}> Ve vlastním vydání</label></div><details><summary>Další otevřený krok</summary><p${latest(a).nextStep?' data-i18n-user':''}>${esc(latest(a).nextStep||'Zatím nepojmenovaný. Přidej ho při další revizi v dílně.')}</p><a href="#workshop">Pokračovat v dílně ↗</a></details></article>`).join('')}</div>`:'<div class="journal-empty"><span>01 → 02 → ?</span><h3>Kronika začíná vlastním pokusem.</h3><p>Ulož v dílně první verzi. Pak ji přepracuj a vysvětli změnu.</p><a href="#workshop">Otevřít dílnu ↗</a></div>'}<div data-journal-detail></div></div>
  <div data-journal-panel="inventory"${view==='inventory'?'':' hidden'}><div class="journal-columns"><section><h3>Materiál s původem</h3><form data-journal-material><input type="hidden" name="id" value=""><label>Druh<select name="type">${Object.entries(TYPES).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label>Název<input name="title" required maxlength="120" placeholder="Tvar podchodu / slovo / barvy"></label><label>Obsah a zamýšlené použití<textarea name="text" required maxlength="6000" rows="4"></textarea></label><label>Původ / URL / vlastní pozorování<input name="source" maxlength="1000" placeholder="Kde materiál vznikl a proč ho mohu použít"></label><button type="submit">Uložit do inventáře +</button><button type="button" data-journal-cancel-edit hidden>Zrušit úpravu</button></form><div class="journal-materials">${inventory.map(i=>`<article><label class="journal-material-select"><input type="checkbox" data-journal-desk="${esc(i.id)}"${desk.has(i.id)?' checked':''}><span>${esc(TYPES[asText(i.type)]||i.type)} / <span data-i18n-user>${esc(i.title)}</span></span></label><p data-i18n-user>${esc(i.text)}</p>${i.source?`<p class="journal-source">Původ: <span data-i18n-user>${safeUrl(i.source)?`<a href="${esc(safeUrl(i.source))}" target="_blank" rel="noopener noreferrer">${esc(i.source)} ↗</a>`:esc(i.source)}</span></p>`:''}<div class="journal-inline"><button type="button" data-journal-edit="${esc(i.id)}">Upravit</button><button type="button" data-journal-remove="${esc(i.id)}">Smazat</button></div></article>`).join('')||'<p>Materiál sbíráš ty. Archiv ti žádné cizí reference nevymýšlí.</p>'}</div></section><section class="journal-desk"><p class="journal-kicker">PŘESUN MATERIÁLU / NOVÁ SOUVISLOST</p><h3>Pracovní stůl</h3><p>Vyber položky vlevo. Šipkami sestavíš pořadí; funguje i bez přetahování.</p><ol>${arr(info.desk).map((id,index)=>{const i=inventory.find(x=>x.id===id);return i?`<li><strong data-i18n-user>${esc(i.title)}</strong><p data-i18n-user>${esc(i.text)}</p><div class="journal-inline"><button type="button" data-journal-move="${esc(id)}" data-delta="-1"${index===0?' disabled':''} aria-label="Posunout ${esc(i.title)} nahoru">↑</button><button type="button" data-journal-move="${esc(id)}" data-delta="1"${index===arr(info.desk).length-1?' disabled':''} aria-label="Posunout ${esc(i.title)} dolů">↓</button></div></li>`:'';}).join('')}</ol><form data-journal-combine><label>Název nové kompozice<input name="title" required maxlength="120"></label><label>Disciplína<select name="discipline">${Object.entries(DISCIPLINES).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></label><label>Proč tyto části spojuji<textarea name="decision" required maxlength="3000" rows="3"></textarea></label><label>Další konkrétní krok<input name="nextStep" required maxlength="1000"></label><button type="submit"${arr(info.desk).length?'':' disabled'}>Sestavit vlastní první verzi ↗</button></form></section></div></div>
  <div data-journal-panel="connections"${view==='connections'?'':' hidden'}><div class="journal-columns"><section><h3>Mapa souvislostí</h3><p>Propojení pojmenuj ty. Žádné automaticky vymyšlené příbuznosti.</p><form data-journal-link><label>Od díla<select name="from" required>${options(state)}</select></label><label>K dílu<select name="to" required>${options(state)}</select></label><label>Společná otázka / rozhodnutí<input name="note" required maxlength="1000"></label><button type="submit"${artifacts.length<2?' disabled':''}>Přidat souvislost +</button></form><div class="journal-links">${arr(info.links).map(l=>`<article><strong>${esc(artifacts.find(a=>a.id===l.from)?.title||'Chybějící dílo')} <span>→</span> ${esc(artifacts.find(a=>a.id===l.to)?.title||'Chybějící dílo')}</strong><p data-i18n-user>${esc(l.note)}</p><button type="button" data-journal-remove-link="${esc(l.id)}">Odebrat propojení</button></article>`).join('')}</div></section><section><h3>Vlastní slovník</h3><form data-journal-word><label>Pojem<input name="term" required maxlength="120"></label><label>Moje vysvětlení a příklad<textarea name="meaning" required maxlength="3000" rows="3"></textarea></label><label>Ukázka v mé práci<select name="artifactId"><option value="">Bez odkazu</option>${options(state)}</select></label><button type="submit">Přidat vlastní pojem +</button></form>${arr(info.vocabulary).map(v=>`<article class="journal-word"><h4 data-i18n-user>${esc(v.term)}</h4><p data-i18n-user>${esc(v.meaning)}</p>${v.artifactId?`<button type="button" data-journal-artifact="${esc(v.artifactId)}">Ukázat vlastní příklad ↗</button>`:''}<button type="button" data-journal-remove-word="${esc(v.id)}">Smazat pojem</button></article>`).join('')}</section></div></div>
  <div data-journal-panel="edition"${view==='edition'?'':' hidden'}><div class="journal-edition"><p class="journal-kicker">NEVEŘEJNÉ / KURÁTORUJEŠ TY</p><h3><span data-i18n-user>${esc(state.profile?.alias||'SELFMADE')}</span><br>VOL. ${String(selected.size).padStart(2,'0')}</h3><p>V kronice vyber díla pro vlastní vydání. HTML obsahuje všechny jejich skutečné verze, palety a uložené tahy; nic nenahrává na server.</p><ul>${artifacts.filter(a=>selected.has(a.id)).map(a=>`<li><span data-i18n-user>${esc(a.title)}</span> / ${arr(a.versions).length} verzí</li>`).join('')||'<li>Zatím žádný vybraný projekt.</li>'}</ul><div class="journal-export-actions"><button type="button" data-journal-export="html">Přenosný Blackbook HTML ↓</button><button type="button" data-journal-export="txt">Textové vydání TXT ↓</button></div><p class="journal-source">Neobsahuje session audio/video. Jejich vlastní stažené soubory uchovej samostatně. HTML můžeš prohlížet offline; veřejné portfolio ani účet tím nevzniká.</p></div></div>
  <div data-journal-panel="backup"${view==='backup'?'':' hidden'}><div class="journal-columns"><section><h3>Záloha pod tvou kontrolou</h3><p>JSON obsahuje lokální profil, díla, verze, inventář a rozpracované zápisky. Uchovej jej soukromě.</p><button type="button" data-journal-export="json">Úplná záloha JSON ↓</button><label>Otevřít dřívější zálohu<input type="file" data-journal-import accept="application/json,.json"></label><div data-journal-import-preview></div></section><section><h3>Co je kde uložené</h3><p>Texty, palety a uložené tahy: úložiště tohoto prohlížeče. Audio/video v dílně: pouze aktuální karta, pokud je samostatně nestáhneš. Serverový účet ani synchronizace mezi zařízeními nejsou zapnuté.</p><p>Starý atlas a expediční zápisník zůstávají oddělené.</p><a href="/#hidden-city">Otevřít původní atlas ↗</a><details class="journal-danger"><summary>Smazat osobní Blackbook</summary><p>Smaže místní díla, inventář, slovník, propojení a kurátorský výběr. Profil, ostatní questy a původní atlas zůstanou.</p><label><input type="checkbox" data-journal-delete-consent> Mám vlastní zálohu a rozumím smazání.</label><button type="button" data-journal-reset>Smazat Blackbook v tomto prohlížeči</button></details></section></div></div>`;
 }
 function showArtifact(id) {
  const a=arr(store.get().artifacts).find(x=>x.id===id);if(!a)return;
  if(view!=='archive'){view='archive';render();}const host=root.querySelector('[data-journal-detail]');host.innerHTML=`<section class="journal-detail" tabindex="-1"><p class="journal-kicker">SKUTEČNÁ ČASOVÁ OSA / ${esc(DISCIPLINES[a.discipline]||a.discipline)}</p><h3 data-i18n-user>${esc(a.title)}</h3><p>Žlutá čára označuje řádek odlišný od předchozí verze. Posunuté řádky mohou být také zvýrazněné; nejde o hodnocení kvality.</p>${arr(a.versions).map((v,i)=>`<details${i===arr(a.versions).length-1?' open':''}><summary>Verze ${i+1} / ${esc(date(v.createdAt))}${i===0?' / PRVNÍ POKUS':''}</summary>${versionHtml(v,a.versions[i-1])}</details>`).join('')}<button type="button" data-journal-close-detail>Zavřít rozbor</button><a href="#workshop">Novou revizi vytvoř v dílně ↗</a></section>`;host.firstElementChild.focus({preventScroll:true});host.scrollIntoView({block:'nearest',behavior:'instant'});
 }
 function handleClick(event) {
  const button=event.target.closest('button');if(!button||!root.contains(button))return;const d=button.dataset;
  if(d.journalView){view=d.journalView;editing=null;importCandidate=null;render();root.querySelector(`[data-journal-view="${view}"]`)?.focus();}
  if(d.journalArtifact)showArtifact(d.journalArtifact);
  if(d.journalCloseDetail!==undefined)root.querySelector('[data-journal-detail]').replaceChildren();
  if(d.journalExport){const state=store.exportData();if(d.journalExport==='json')download('caisik-selfmade-backup.json',JSON.stringify(state,null,2),'application/json;charset=utf-8');if(d.journalExport==='txt')download('caisik-blackbook.txt',notebookText(store.get()),'text/plain;charset=utf-8');if(d.journalExport==='html')download('caisik-blackbook.html',renderPortableNotebook(store.get()),'text/html;charset=utf-8');}
  if(d.journalEdit){const item=arr(store.get().inventory).find(i=>i.id===d.journalEdit),form=root.querySelector('[data-journal-material]');if(!item)return;editing=item.id;for(const key of ['id','type','title','text','source'])form.elements[key].value=asText(item[key]);form.querySelector('[type=submit]').textContent='Uložit úpravu';form.querySelector('[data-journal-cancel-edit]').hidden=false;form.elements.title.focus();}
  if(d.journalCancelEdit!==undefined){editing=null;render();}
  if(d.journalRemove){persist(s=>{s.inventory=s.inventory.filter(i=>i.id!==d.journalRemove);if(s.drafts.journal?.desk)s.drafts.journal.desk=s.drafts.journal.desk.filter(id=>id!==d.journalRemove);});render();saved('Položka byla odebrána z inventáře i stolu.');}
  if(d.journalMove){updateMeta(j=>{const desk=arr(j.desk),index=desk.indexOf(d.journalMove),next=index+Number(d.delta);if(index>=0&&next>=0&&next<desk.length)[desk[index],desk[next]]=[desk[next],desk[index]];j.desk=desk;});render();root.querySelector(`[data-journal-move="${d.journalMove}"][data-delta="${d.delta}"]`)?.focus();}
  if(d.journalRemoveLink){updateMeta(j=>j.links=arr(j.links).filter(l=>l.id!==d.journalRemoveLink));render();}
  if(d.journalRemoveWord){updateMeta(j=>j.vocabulary=arr(j.vocabulary).filter(v=>v.id!==d.journalRemoveWord));render();}
  if(d.journalReset!==undefined){if(!root.querySelector('[data-journal-delete-consent]')?.checked){message('Nejdřív potvrď, že rozumíš smazání a máš zálohu.');return;}persist(s=>{s.artifacts=[];s.inventory=[];delete s.drafts.journal;});render();saved('Osobní Blackbook byl smazán. Původní atlas zůstává.');}
  if(d.journalConfirmImport!==undefined){if(!importCandidate)return;const selected=[...root.querySelectorAll('[data-import-artifact]:checked')].map(el=>el.dataset.importArtifact),payload=JSON.parse(JSON.stringify(importCandidate));payload.artifacts=arr(payload.artifacts).filter(a=>selected.includes(a.id));try {const result=store.importData(payload);if(result===false){message('Obnova nebyla trvale uložena. Uchovej původní zálohu.');return;}importCandidate=null;render();message('Vybraná díla a další materiál byly sloučeny. Stávající verze zůstaly zachované.');}catch(error){message(`Obnova odmítnuta: ${error.message}`);}}
 }
 function handleInput(event) {
  if(event.target.hasAttribute('data-journal-world-step'))root.querySelector('[data-journal-world]').innerHTML=baseScene(store.get(),Number(event.target.value));
 }
 async function handleChange(event) {
  const target=event.target,d=target.dataset;
  if(d.journalCurate){updateMeta((j,s)=>{const selected=new Set(j.selected===undefined?s.artifacts.map(a=>a.id):j.selected);target.checked?selected.add(d.journalCurate):selected.delete(d.journalCurate);j.selected=[...selected];});}
  if(d.journalDesk){updateMeta(j=>{const selected=new Set(arr(j.desk));target.checked?selected.add(d.journalDesk):selected.delete(d.journalDesk);j.desk=[...selected];});render();}
  if(d.journalBase!==undefined){updateMeta(j=>j.base=target.value);root.querySelector('[data-journal-world]').innerHTML=baseScene(store.get());saved('Podoba základny byla uložena.');}
  if(d.journalImport!==undefined){const file=target.files?.[0],host=root.querySelector('[data-journal-import-preview]');if(!file)return;if(file.size>8*1024*1024){message('Záloha přesahuje limit 8 MB. Soubor nebyl načten.');target.value='';return;}try {const parsed=JSON.parse(await file.text());if(destroyed)return;const preview=store.previewImport(parsed);importCandidate=parsed;host.innerHTML=`<div class="journal-import-preview"><h4>Náhled obnovy</h4><p>Formát byl ověřen. Vyber projekty k přidání; jejich verze se sloučí podle trvalých ID. Inventář, slovník a další platná data zálohy se také sloučí.</p>${arr(parsed.artifacts).map(a=>`<label><input type="checkbox" data-import-artifact="${esc(a.id)}" checked> <span data-i18n-user>${esc(a.title)}</span> / ${arr(a.versions).length} verzí</label>`).join('')||'<p>Soubor neobsahuje díla.</p>'}<button type="button" data-journal-confirm-import>Sloučit vybranou zálohu</button></div>`;message('Záloha čeká na potvrzení. Zatím se nic neobnovilo.');void preview;}catch(error){importCandidate=null;host.replaceChildren();message(`Záloha nebyla přijata: ${error.message}`);}finally{target.value='';}}
 }
 function handleSubmit(event) {
  const form=event.target;if(!(form instanceof HTMLFormElement))return;const value=name=>String(form.elements[name]?.value||'').trim();
  if(form.hasAttribute('data-journal-material')){event.preventDefault();const title=value('title'),text=value('text');if(!title||!text)return;const id=editing||uid();persist(s=>{const found=s.inventory.find(i=>i.id===id),item={id,type:value('type'),title,text,source:value('source'),createdAt:found?.createdAt||stamp(),updatedAt:stamp()};if(found)Object.assign(found,item);else s.inventory.push(item);});editing=null;render();saved('Vlastní materiál je v inventáři.');}
  if(form.hasAttribute('data-journal-combine')){event.preventDefault();const state=store.get(),materials=arr(meta(state).desk).map(id=>state.inventory.find(i=>i.id===id)).filter(Boolean);if(!materials.length)return;const createdAt=stamp(),artifact={id:uid(),discipline:value('discipline'),title:value('title'),createdAt,updatedAt:createdAt,versions:[{id:uid(),createdAt,text:materials.map(i=>`${asText(i.title)}\n${asText(i.text)}`).join('\n\n'),decision:value('decision'),nextStep:value('nextStep'),palette:[],strokes:[]}]};if(!artifact.title||!artifact.versions[0].decision||!artifact.versions[0].nextStep)return;persist(s=>{s.artifacts.push(artifact);s.events.push({id:uid(),type:'artifact',artifactId:artifact.id,createdAt});});view='archive';render();showArtifact(artifact.id);saved('První autorská kompozice je uložená. Materiál zůstává v inventáři.');}
  if(form.hasAttribute('data-journal-link')){event.preventDefault();if(value('from')===value('to')){message('Vyber dvě různá díla.');return;}if(!value('from')||!value('to')||!value('note'))return;updateMeta(j=>{j.links ||= [];j.links.push({id:uid(),from:value('from'),to:value('to'),note:value('note')});});render();saved('Souvislost je zaznamenaná.');}
  if(form.hasAttribute('data-journal-word')){event.preventDefault();if(!value('term')||!value('meaning'))return;updateMeta(j=>{j.vocabulary ||= [];j.vocabulary.push({id:uid(),term:value('term'),meaning:value('meaning'),artifactId:value('artifactId')});});render();saved('Pojem je ve tvém slovníku.');}
 }
 render();root.addEventListener('click',handleClick);root.addEventListener('change',handleChange);root.addEventListener('input',handleInput);root.addEventListener('submit',handleSubmit);root.addEventListener('toggle',handleToggle,true);
 // Preserve in-progress form edits when another workshop saves. Refresh on explicit re-entry.
 unsubscribe=store.subscribe(()=>{if(!root.contains(document.activeElement))render();});
 return ()=>{destroyed=true;unsubscribe();root.removeEventListener('click',handleClick);root.removeEventListener('change',handleChange);root.removeEventListener('input',handleInput);root.removeEventListener('submit',handleSubmit);root.removeEventListener('toggle',handleToggle,true);preparedExport=null;objectUrls.forEach(url=>URL.revokeObjectURL(url));objectUrls=[];root.replaceChildren();};
}
